import math
def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])
def find_zero(xs: list):
    a = 0.0
    fa = poly(xs, a)
    if fa == 0.0:
        return a

    found = False
    b = 1.0
    fb = poly(xs, b)
    if fb == 0.0:
        return b
    if fa * fb < 0:
        found = True
    else:
        # Expand in positive direction
        for _ in range(100):
            b *= 2
            fb = poly(xs, b)
            if fb == 0.0:
                return b
            if fa * fb < 0:
                found = True
                break

    if not found:
        # Try negative direction
        b_neg = -1.0
        fb_neg = poly(xs, b_neg)
        if fb_neg == 0.0:
            return b_neg
        if fa * fb_neg < 0:
            found = True
            b = b_neg
            fb = fb_neg
        else:
            # Expand in negative direction
            for _ in range(100):
                b_neg *= 2
                fb_neg = poly(xs, b_neg)
                if fb_neg == 0.0:
                    return b_neg
                if fa * fb_neg < 0:
                    found = True
                    b = b_neg
                    fb = fb_neg
                    break

    # Determine the interval
    left = min(a, b)
    right = max(a, b)
    fl = poly(xs, left)
    fr = poly(xs, right)

    # Bisection method
    for _ in range(100):
        mid = (left + right) / 2
        fm = poly(xs, mid)
        if fm == 0.0:
            return mid
        if fl * fm < 0:
            right = mid
            fr = fm
        else:
            left = mid
            fl = fm

    return (left + right) / 2

