        return False
    factors = []
    # Factor out all 2s
    while a % 2 == 0:
        factors.append(2)
        a = a // 2
    # Check for odd factors starting from 3
    i = 3
    while i * i <= a:
        while a % i == 0:
            factors.append(i)
            a = a // i
        i += 2
    # If remaining a is a prime number greater than 2
    if a > 1:
        factors.append(a)
    return len(factors) == 3

