        # Check all four possible directions
        if current_x > 0:
            neighbors.append((current_x - 1, current_y))
        if current_x < N - 1:
            neighbors.append((current_x + 1, current_y))
        if current_y > 0:
            neighbors.append((current_x, current_y - 1))
        if current_y < N - 1:
            neighbors.append((current_x, current_y + 1))

        # Find the neighbor with the smallest value
        min_next_val = float('inf')
        best_x, best_y = current_x, current_y
        for x, y in neighbors:
            if grid[x][y] < min_next_val:
                min_next_val = grid[x][y]
                best_x, best_y = x, y

        current_x, current_y = best_x, best_y
        path.append(min_next_val)

    return path

